Python:
def cal(a, n, s):
    i, x, y = 0, 0, 0
    for j in range(n):
        x += a[j]
        while x > s:
            x -= a[i]
            i += 1
        y += j - i + 1
    return y

C++:
int cal(int a[], int n, int s){
    int i = 0, x = 0, y = 0;
    for(int j = 0; j < n; j++){
        x += a[j];
        while(x > s) {
            x -= a[i];
            i++;
        }
        y += j - i + 1;
    }
    return y;
}
