Python:
def sumSpecialNumbers(n):
    total = 0
    for i in range(1, n + 1):
        if i % 3 == 1:
            total += i
    return total

C++:
int sumSpecialNumbers(int n) {
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        if (i % 3 == 1) {
            sum += i;
        }
    }
    return sum;
}
